candidates.raw:
wd_mode_t prev_mode;
adcs_vec3_t h, b_unit, par, perp, dipole;
adcs_status_t st;
double bnorm, bdot, mag;
size_t i;
int valid = 1;
adcs_actuator_command_t cmd;

if ((wd_input.enable != 0) && (wd_input.enable != 1)) {
    valid = 0;
}

if ((wd_input.enable == 0) && (valid)) {
    wd_state.mode = WD_OFF;
    wd_state.high_cycles = 0U;
    wd_state.low_cycles = 0U;
    wd_state.elapsed = 0U;
    wd_output.mode = WD_OFF;
    wd_output.high_cycles = 0U;
    wd_output.low_cycles = 0U;
    wd_output.elapsed = 0U;
    wd_output.saturation_mask = 0U;
    wd_output.dumpable_magnitude_nms = 0.0;
    wd_output.momentum_nms = (adcs_vec3_t){0.0, 0.0, 0.0};
    wd_output.parallel_momentum_nms = (adcs_vec3_t){0.0, 0.0, 0.0};
    wd_output.dumpable_momentum_nms = (adcs_vec3_t){0.0, 0.0, 0.0};
    wd_output.dipole_a_m2 = (adcs_vec3_t){0.0, 0.0, 0.0};
    wd_output.torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    return;
}

if (wd_input.wheel_count != 4U) valid = 0;
if ((wd_input.wheels == NULL) || (wd_input.field_body_t == NULL)) valid = 0;

if (valid) {
    if (!adcs_is_finite_vec3(wd_input.field_body_t)) {
        valid = 0;
    } else {
        bnorm = adcs_vec3_norm(wd_input.field_body_t);
        if (!(isfinite(bnorm)) || (bnorm <= ADCS_EPS_NORM)) valid = 0;
    }
}

if (valid) {
    if (!isfinite(wd_config.start_nms) || !isfinite(wd_config.stop_nms) ||
        !isfinite(wd_config.max_wheel_speed_rad_s) || !isfinite(wd_config.gain_s_inv) ||
        !isfinite(wd_config.max_dipole_a_m2) ||
        (wd_config.stop_nms < 0.0) ||
        !(wd_config.stop_nms < wd_config.start_nms) ||
        !(wd_config.max_wheel_speed_rad_s > 0.0) ||
        (wd_config.gain_s_inv < 0.0) || (wd_config.max_dipole_a_m2 < 0.0)) {
        valid = 0;
    }
}

if (valid) {
    if ((wd_config.required_high < 1U) || (wd_config.required_high > 100U) ||
        (wd_config.required_low < 1U) || (wd_config.required_low > 100U) ||
        (wd_config.minimum_dump_cycles < 1U) || (wd_config.minimum_dump_cycles > 100U) ||
        (wd_config.cooldown_cycles < 1U) || (wd_config.cooldown_cycles > 100U)) {
        valid = 0;
    }
}

if (valid) {
    for (i = 0; i < 4U; i++) {
        adcs_vec3_t axis;
        if (!isfinite(wd_input.wheels[i].inertia_kg_m2) ||
            (wd_input.wheels[i].inertia_kg_m2 < 0.0) ||
            !isfinite(wd_input.wheels[i].speed_rad_s) ||
            (fabs(wd_input.wheels[i].speed_rad_s) > wd_config.max_wheel_speed_rad_s) ||
            (adcs_vec3_normalize(&wd_input.wheels[i].axis_body, ADCS_EPS_NORM, &axis) !=
             ADCS_OK)) {
            valid = 0;
            break;
        }
    }
}

if (!valid) {
    wd_state.mode = WD_FAULT;
    wd_state.high_cycles = 0U;
    wd_state.low_cycles = 0U;
    wd_state.elapsed = 0U;
    wd_output.mode = WD_FAULT;
    wd_output.high_cycles = 0U;
    wd_output.low_cycles = 0U;
    wd_output.elapsed = 0U;
    wd_output.saturation_mask = 0U;
    wd_output.dumpable_magnitude_nms = 0.0;
    wd_output.momentum_nms = (adcs_vec3_t){0.0, 0.0, 0.0};
    wd_output.parallel_momentum_nms = (adcs_vec3_t){0.0, 0.0, 0.0};
    wd_output.dumpable_momentum_nms = (adcs_vec3_t){0.0, 0.0, 0.0};
    wd_output.dipole_a_m2 = (adcs_vec3_t){0.0, 0.0, 0.0};
    wd_output.torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    return;
}

st = adcs_wheel_momentum(wd_input.wheels, wd_input.wheel_count, &h);
if (st != ADCS_OK) {
    wd_state.mode = WD_FAULT;
    wd_state.high_cycles = 0U;
    wd_state.low_cycles = 0U;
    wd_state.elapsed = 0U;
    wd_output.mode = WD_FAULT;
    wd_output.high_cycles = 0U;
    wd_output.low_cycles = 0U;
    wd_output.elapsed = 0U;
    wd_output.saturation_mask = 0U;
    wd_output.dumpable_magnitude_nms = 0.0;
    wd_output.momentum_nms = (adcs_vec3_t){0.0, 0.0, 0.0};
    wd_output.parallel_momentum_nms = (adcs_vec3_t){0.0, 0.0, 0.0};
    wd_output.dumpable_momentum_nms = (adcs_vec3_t){0.0, 0.0, 0.0};
    wd_output.dipole_a_m2 = (adcs_vec3_t){0.0, 0.0, 0.0};
    wd_output.torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    return;
}

b_unit = adcs_vec3_scale(wd_input.field_body_t, 1.0 / bnorm);
bdot = adcs_vec3_dot(&h, &b_unit);
par = adcs_vec3_scale(&b_unit, bdot);
perp = adcs_vec3_sub(&h, &par);
mag = adcs_vec3_norm(&perp);

wd_output.momentum_nms = h;
wd_output.parallel_momentum_nms = par;
wd_output.dumpable_momentum_nms = perp;
wd_output.dumpable_magnitude_nms = mag;

prev_mode = wd_state.mode;
if (prev_mode == WD_FAULT) {
    /* latched */
} else if (prev_mode == WD_OFF) {
    wd_state.high_cycles = 0U;
    wd_state.low_cycles = 0U;
    wd_state.elapsed = 0U;
    if (mag >= wd_config.start_nms) {
        wd_state.high_cycles = 1U;
        if (wd_state.high_cycles >= wd_config.required_high) {
            wd_state.mode = WD_DUMPING;
            wd_state.high_cycles = 0U;
            wd_state.low_cycles = 0U;
            wd_state.elapsed = 0U;
        } else {
            wd_state.mode = WD_ARMING;
        }
    } else {
        wd_state.mode = WD_OFF;
    }
} else if (prev_mode == WD_ARMING) {
    if (mag >= wd_config.start_nms) {
        wd_state.high_cycles++;
        if (wd_state.high_cycles >= wd_config.required_high) {
            wd_state.mode = WD_DUMPING;
            wd_state.high_cycles = 0U;
            wd_state.low_cycles = 0U;
            wd_state.elapsed = 0U;
        }
    } else {
        wd_state.high_cycles = 0U;
        wd_state.mode = WD_OFF;
    }
} else if (prev_mode == WD_DUMPING) {
    wd_state.elapsed++;
    if (wd_state.elapsed >= wd_config.minimum_dump_cycles) {
        if (mag <= wd_config.stop_nms) {
            wd_state.low_cycles++;
            if (wd_state.low_cycles >= wd_config.required_low) {
                wd_state.mode = WD_COOLDOWN;
                wd_state.high_cycles = 0U;
                wd_state.low_cycles = 0U;
                wd_state.elapsed = 0U;
            }
        } else if (mag > wd_config.stop_nms) {
            wd_state.low_cycles = 0U;
        }
    }
} else if (prev_mode == WD_COOLDOWN) {
    wd_state.elapsed++;
    if (wd_state.elapsed >= wd_config.cooldown_cycles) {
        wd_state.mode = WD_OFF;
        wd_state.high_cycles = 0U;
        wd_state.low_cycles = 0U;
        wd_state.elapsed = 0U;
    }
}

wd_output.mode = wd_state.mode;
wd_output.high_cycles = wd_state.high_cycles;
wd_output.low_cycles = wd_state.low_cycles;
wd_output.elapsed = wd_state.elapsed;

if ((wd_state.mode == WD_OFF) || (wd_state.mode == WD_COOLDOWN) ||
    (wd_state.mode == WD_FAULT)) {
    wd_output.dipole_a_m2 = (adcs_vec3_t){0.0, 0.0, 0.0};
    wd_output.torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    wd_output.saturation_mask = 0U;
} else {
    dipole = (adcs_vec3_t){0.0, 0.0, 0.0};
    cmd.command = dipole;
    cmd.saturated_axes = 0U;
    st = adcs_momentum_unload_dipole(&perp, wd_input.field_body_t, wd_config.gain_s_inv,
                                     wd_config.max_dipole_a_m2, &cmd, &dipole);
    if (st != ADCS_OK) {
        wd_output.dipole_a_m2 = (adcs_vec3_t){0.0, 0.0, 0.0};
        wd_output.torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
        wd_output.saturation_mask = 0U;
    } else {
        wd_output.dipole_a_m2 = cmd.command;
        wd_output.torque_nm = dipole;
        wd_output.saturation_mask = cmd.saturated_axes;
    }
}

